centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
armsets={(r,c):k for k,(rr,cc,v) in enumerate(centers) for r,c in [(rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)]}
orig=[[0]*19 for _ in range(19)]
for k,(r,c,v) in enumerate(centers):
    orig[r][c]=v
    for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]: orig[rr][cc]=3
for r,c in [(9,8),(10,7),(10,9),(11,8)]: orig[r][c]=3
# color each directional ray, with other crosses' arms blocking; retain markers
h=[[0]*19 for _ in range(19)]; vgrid=[[0]*19 for _ in range(19)]
for k,(r,c,color) in enumerate(centers):
    h[r][c]=color; vgrid[r][c]=color
    for dr,dc,target in [(0,-1,h),(0,1,h),(-1,0,vgrid),(1,0,vgrid)]:
        rr,cc=r+dr,c+dc
        while 0<=rr<19 and 0<=cc<19:
            if orig[rr][cc]==3 and armsets.get((rr,cc)) != k:
                break
            if orig[rr][cc]!=3: target[rr][cc]=color
            rr+=dr; cc+=dc
# combine horizontal then vertical, with originals retained
out=[row[:] for row in orig]
for i in range(19):
    for j in range(19):
        if orig[i][j]==3: out[i][j]=3
        else:
            if h[i][j]: out[i][j]=h[i][j]
            if vgrid[i][j]: out[i][j]=vgrid[i][j]
print('\n'.join(' '.join(map(str,row)) for row in out))
